package glitch

import data.glitch_lib

is_insecure_integrity_attr(attr) {
    attr.name == "protocol"
    attr.value.ir_type == "String"
    regex.match("(?i)^(http|ftp|udp)$", attr.value.value)
} else {
    attr.name == "ssl"
    attr.value.ir_type == "Boolean"
    attr.value.value == false
} else {
    attr.name == "encryption"
    attr.value.ir_type == "String"
    regex.match("(?i)disabled|none", attr.value.value)
} else {
    attr.name == "checksum"
    attr.value.ir_type == "Boolean"
    attr.value.value == false
} else {
    attr.name == "security_policy"
    attr.value.ir_type == "String"
    regex.match("(?i)none|permissive|weak", attr.value.value)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    is_insecure_integrity_attr(attr)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing support for integrity check in transmission protocol - Use secure protocols like HTTPS with TLS enforcement. (CWE-353)"
    }
}

