package glitch

import data.glitch_lib

insecure_url_pattern := "(?i)^(http|ftp|udp)://"

check_value_for_insecure_url(value) {
    value.ir_type == "String"
    regex.match(insecure_url_pattern, value.value)
} else {
    value.ir_type == "Hash"
    some key, val in value.value
    check_value_for_insecure_url(val)
} else {
    value.ir_type == "Array"
    some element in value.value
    check_value_for_insecure_url(element)
} else {
    value.ir_type == "Sum"
    check_value_for_insecure_url(value.left)
    check_value_for_insecure_url(value.right)
}

